"""TPAT3 ส่วนที่ 2 · ความคิดและความสนใจทางวิทยาศาสตร์

โจทย์ทั้งหมดแต่งขึ้นใหม่ ข่าวสั้นเป็นสถานการณ์สมมติและไม่ผูกกับปี ผลิตภัณฑ์ หรือสถิติล่าสุด
"""
from author import *

