C = "tpat3.thinking.current_awareness."
SRC = ["ผังการสอบ TPAT3 จาก mytcas.com/blueprint/tpat3-30/", "หลักวิทยาศาสตร์และวิศวกรรมพื้นฐาน"]


def course(tid, title, subtitle, concept_md, tech_name, tech_body, pit_title, pit_wrong, pit_why, pit_correct, pit_tag, example_stem, example_steps, example_answer, check_stem, check_choices, check_answer, check_explain, prereq=None, nxt=None):
    return lesson(tid, title, subtitle,
        objectives=["อธิบายแนวคิดหลักของหัวข้อนี้ได้", "เลือกข้อมูลและวิธีคิดที่ตรงกับสถานการณ์", "ตรวจคำตอบและหลีกเลี่ยงกับดักที่พบบ่อย"],
        minutes=30, prereq=prereq or [], nxt=nxt or [],
        blocks=[
            hook(subtitle), concept("แนวคิดหลัก", concept_md),
            technique(tech_name, "เมื่อโจทย์ให้ข้อมูลหลายชิ้นหรือต้องตัดสินใจหลายขั้น", "อย่าใช้สูตรหรือหลักการโดยไม่ตรวจเงื่อนไขของสถานการณ์", tech_body, tip=tech_name),
            example("ตัวอย่าง", example_stem, example_steps, example_answer),
            pitfall(pit_title, pit_wrong, pit_why, pit_correct, pit_tag),
            summary("ระบุสิ่งที่โจทย์ถามก่อน", "เลือกหลักการที่ตรงเงื่อนไข", "คำนวณหรือให้เหตุผลทีละขั้น", "ตรวจหน่วย ขนาด และข้อจำกัดก่อนตอบ"),
            check(check_stem, check_choices, check_answer, check_explain),
        ], patterns=[tech_name, pit_title], sources=SRC)


def N(stem, ans, wrong, steps, hints, explain, diff=3, sec=120, tags=None):
    return q(stem, ans, wrong, steps, hints, explain, diff=diff, sec=sec, reading="high" if diff >= 4 else "medium", tags=tags)


def balance_new(items, difficulties):
    """ปรับเฉพาะ 4 ข้อใหม่ให้เติมระดับที่ขาด โดยไม่แตะระดับของ 6 ข้อเดิม."""
    if len(items) == 10:
        time_caps = {1: 55, 2: 90, 3: 120, 4: 140, 5: 150}
        for item, difficulty in zip(items[-4:], difficulties):
            item["diff"] = difficulty
            item["sec"] = min(item["sec"], time_caps[difficulty])
            item["reading"] = "low" if difficulty <= 2 else ("medium" if difficulty == 3 else "high")
    return items


